void syscall_entry_handler(void *ignore, struct pt_regs *regs, long id) {
    int syscall_number = regs->syscallno;
    if (syscall_number < 0 || !is_syscall_enabled(syscall_number)) {
        return;
    }

    struct syscall_metadata *metadata = get_syscall_metadata(syscall_number);
    if (!metadata || metadata->event_count == 0) {
        return;
    }

    unsigned int size = sizeof(struct syscall_trace_record) + metadata->arg_count * sizeof(unsigned long);
    size = ALIGN(size, 8);

    struct syscall_trace_record *record = (struct syscall_trace_record *)__get_tracing_buffer(size);
    if (!record) {
        return;
    }

    record->syscall_id = syscall_number;
    for (int i = 0; i < metadata->arg_count; i++) {
        record->arguments[i] = regs->args[i];
    }

    record->record_size = size;
    submit_trace_record((struct trace_record *)record);
}

void syscall_enter_handler(void* ignore, struct pt_regs* regs, long id) {
    int syscall_nr = pt_regs_get_arg1(regs);
    if (syscall_nr < 0 || !syscall_enabled(syscall_nr)) {
        return;
    }

    struct syscall_metadata* metadata = get_syscall_metadata(syscall_nr);
    if (!metadata || metadata->record_size == 0) {
        return;
    }

    size_t size = metadata->record_size;
    size_t aligned_size = ALIGN(size, 8);

    struct trace_record* record = allocate_trace_record(aligned_size);
    if (!record) {
        return;
    }

    prepare_syscall_enter_record(record, regs, id, metadata);
    submit_trace_record(record);
}

void syscall_trace_enter(void *ignore, struct pt_regs *regs, long id)
{
    int syscall_nr = PT_REGS_SYSCALL_NR(regs);
    struct syscall_metadata *meta;

    if (!syscalls_valid(syscall_nr) || !syscalls_enabled(syscall_nr))
        return;

    meta = get_syscall_metadata(syscall_nr);
    if (!meta || !(meta->event & TRACE_EVENT))
        return;

    struct trace_record *record;
    size_t size = sizeof(*record) + meta->arg_num * sizeof(struct syscall_arg);
    size = ALIGN(size, 8);

    record = alloc_trace_record(size);
    if (!record)
        return;

    record->type = TRACE_SYSCALL_ENTER;
    record->syscall_id = id;
    record->timestamp = get_timestamp();

    for (int i = 0; i < meta->arg_num; ++i) {
        record->args[i].nr = i;
        record->args[i].val = PT_REGS_PARM(regs, i + 1);
    }

    submit_trace_record(record);
}

void syscall_enter_handler(void *ignore, struct pt_regs *regs, long id)
{
    int syscall_nr = pt_regs_SYSCALL_NR(regs);
    struct syscall_metadata *meta;

    if (syscall_nr < 0 || !is_syscall_enabled(syscall_nr))
        return;

    meta = get_syscall_metadata(syscall_nr);
    if (!meta)
        return;

    if (meta->flags & SYS_CALL_FLAG_NO_TRACE)
        return;

    size_t size = syscall_record_size(meta);
    size = ALIGN(size, 8);

    struct trace_record *record = get_free_trace_record();
    if (!record)
        return;

    fill_trace_record(record, meta, regs);
    submit_trace_record(record);
}

void syscall_trace_entry(void *ignore, struct pt_regs *regs, long id) {
    int syscall_number = pt_regs_SYSCALL(regs);
    struct syscall_metadata *meta = get_syscall_metadata(syscall_number);

    if (!meta || !meta->enabled)
        return;

    int nr_args = meta->nr_args;
    int event_size = sizeof(struct syscall_event) + nr_args * sizeof(u64);
    event_size = ALIGN(event_size, 8);

    struct syscall_event *event = prepare_trace_record(event_size);

    if (!event)
        return;

    event->nr = syscall_number;
    event->id = id;

    for (int i = 0; i < nr_args; i++) {
        event->args[i] = pt_regs_arg(regs, i);
    }

    submit_trace_record(event, event_size);
}
